import React, { useState, useRef, useCallback } from 'react';
import styled from '@emotion/styled';
import { theme } from '@atlantis/shared';
import { EditorPane } from './components/EditorPane';
import { PreviewPane } from './components/PreviewPane';
import { ExamplesMenu } from './components/ExamplesMenu';
import { DEFAULT_CONTENT } from './examples';

// ─── Layout ──────────────────────────────────────────────────────────────────

const Wrapper = styled.div`
  display: flex;
  flex-direction: column;
  height: 100vh;
  background: ${theme.colors.mainBg};
  font-family: ${theme.typography.fontFamily};
  color: ${theme.colors.mainText};
  overflow: hidden;
`;

const TopBar = styled.header`
  display: flex;
  align-items: center;
  height: 48px;
  background: ${theme.colors.sidebarBg};
  border-bottom: 1px solid ${theme.colors.sidebarBorder};
  padding: 0 ${theme.spacing.lg};
  flex-shrink: 0;
  gap: ${theme.spacing.md};
  z-index: 100;
`;

const AtlantisLogo = styled.button`
  display: flex;
  align-items: baseline;
  padding: 0;
  background: none;
  border: none;
  cursor: pointer;
  font-family: ${theme.typography.fontFamily};
  font-size: ${theme.typography.fontSizeBase};
  font-weight: 700;
  letter-spacing: -0.02em;
  color: ${theme.colors.mainText};
  flex-shrink: 0;
  transition: opacity 0.15s;
  &:hover { opacity: 0.8; }
  span { color: ${theme.colors.accent}; }
`;

const TitleSep = styled.span`
  color: ${theme.colors.border};
  margin: 0 2px;
  font-weight: 400;
`;

const AppTitle = styled.div`
  font-size: ${theme.typography.fontSizeBase};
  font-weight: 700;
  color: ${theme.colors.mainText};
  letter-spacing: -0.01em;
  flex-shrink: 0;
`;

const AppTitleSub = styled.span`
  font-weight: 400;
  color: ${theme.colors.sidebarTextMuted};
  margin-left: 4px;
  font-size: 12px;
`;

const Spacer = styled.div`
  flex: 1;
`;

const Body = styled.div`
  display: flex;
  flex: 1;
  overflow: hidden;
`;

// ─── Component ───────────────────────────────────────────────────────────────

interface AppProps {
  topBarRight?: React.ReactNode;
}

export default function App({ topBarRight }: AppProps) {
  const [content, setContent] = useState(DEFAULT_CONTENT);
  const [editorCollapsed, setEditorCollapsed] = useState(false);
  const [previewCollapsed, setPreviewCollapsed] = useState(false);

  const editorRef = useRef<HTMLTextAreaElement>(null);
  const previewRef = useRef<HTMLDivElement>(null);
  // Prevents scroll events triggered by programmatic scrolling from causing loops
  const syncingFrom = useRef<'editor' | 'preview' | null>(null);

  const handleEditorScroll = useCallback((e: React.UIEvent<HTMLTextAreaElement>) => {
    if (syncingFrom.current === 'preview') return;
    const el = e.currentTarget;
    const ratio = el.scrollTop / (el.scrollHeight - el.clientHeight);
    if (!previewRef.current) return;
    syncingFrom.current = 'editor';
    const target = previewRef.current;
    target.scrollTop = ratio * (target.scrollHeight - target.clientHeight);
    requestAnimationFrame(() => { syncingFrom.current = null; });
  }, []);

  const handlePreviewScroll = useCallback((e: React.UIEvent<HTMLDivElement>) => {
    if (syncingFrom.current === 'editor') return;
    const el = e.currentTarget;
    const ratio = el.scrollTop / (el.scrollHeight - el.clientHeight);
    if (!editorRef.current) return;
    syncingFrom.current = 'preview';
    const target = editorRef.current;
    target.scrollTop = ratio * (target.scrollHeight - target.clientHeight);
    requestAnimationFrame(() => { syncingFrom.current = null; });
  }, []);

  const handleToggleEditor = () => {
    if (!editorCollapsed && previewCollapsed) setPreviewCollapsed(false);
    setEditorCollapsed((c) => !c);
  };

  const handleTogglePreview = () => {
    if (!previewCollapsed && editorCollapsed) setEditorCollapsed(false);
    setPreviewCollapsed((c) => !c);
  };

  return (
    <Wrapper>
      <TopBar>
        <AtlantisLogo onClick={() => { window.location.hash = '#/home'; }} title="Home">
          Atl<span>antis</span>
        </AtlantisLogo>
        <TitleSep>/</TitleSep>
        <AppTitle>
          MD Editor
          <AppTitleSub>live preview</AppTitleSub>
        </AppTitle>
        <Spacer />
        <ExamplesMenu onSelect={setContent} />
        {topBarRight && topBarRight}
      </TopBar>

      <Body>
        <EditorPane
          value={content}
          onChange={setContent}
          collapsed={editorCollapsed}
          onToggleCollapse={handleToggleEditor}
          scrollRef={editorRef}
          onScroll={handleEditorScroll}
        />
        <PreviewPane
          content={content}
          collapsed={previewCollapsed}
          onToggleCollapse={handleTogglePreview}
          scrollRef={previewRef}
          onScroll={handlePreviewScroll}
        />
      </Body>
    </Wrapper>
  );
}
